/* Venn prototype — public marketing website (hash routes). Prototype copy: every claim must be verified before launch. */
const NAVL = [['product', 'Product'], ['solutions', 'Solutions'], ['security', 'Security'], ['pricing', 'Pricing'], ['about', 'About']];
const cta = (t = 'Book a demo') => `<a class="btn btn-primary btn-lg" href="#/contact">${t}</a>`;
const sec = (h, lead, body, alt = '', id = '') => `<section class="sec ${alt}" ${id ? `id="${id}"` : ''}><div class="wrap"><h2>${h}</h2>${lead ? `<p class="lead">${lead}</p>` : ''}${body}</div></section>`;
const feat = (i, h, p) => `<div class="feat"><div class="ic">${ic(i)}</div><h3>${h}</h3><p class="muted">${p}</p></div>`;
const FAQ = [['Is Venn an accounting system?', 'No. Your accounting system stays the book of record. Venn reads your invoices and payments, finds where they disagree, and helps your team investigate.'], ['Does Venn move money?', 'No. Venn never sends, refunds or collects payments. When a refund is approved, Venn records the decision and you make the payment from your own bank.'], ['How does Venn avoid making things up?', 'Amounts and dates are calculated by code from your records. Every statement from the AI must cite evidence, and claims from emails are shown as unverified until a bank record confirms them.'], ['What happens to my email data?', 'Venn reads only messages matching a financial filter you can see, and you can disconnect at any time, choosing whether to keep or delete what was synced.'], ['Which integrations are live?', 'This is a prototype. Planned for the first release: CSV and PDF import, Gmail, QuickBooks Online and Stripe (read-only). Outlook, Xero and bank feeds follow.'], ['Can I use it without connecting anything?', 'Yes. Upload CSV exports of invoices and payments and Venn starts reconciling.'], ['Who can approve what?', 'Owners approve write-offs, credits, refunds and final notices. AR Specialists prepare and request. Permissions are enforced on the server.']];
const mini = `<div class="mini" aria-label="Product preview with demo data"><div style="padding:12px 16px;border-bottom:1px solid var(--border);display:flex;gap:8px;align-items:center"><b>INVG-0001</b><span class="badge b-amber">Ready for review</span><span class="sp"></span><span class="cap">Demo data</span></div><div style="padding:16px" class="col"><div><b>Short payment on INV-1042</b><div class="small muted">Invoice issued for 5,000.00 USD; one verified payment of 4,000.00 received.</div></div><div class="finding f-fact" style="margin:0"><div class="h">${ic('check')} Confirmed</div>One bank payment of 4,000.00 USD was received 9 Oct. <span class="cite">E2</span></div><div class="finding f-calc" style="margin:0"><div class="h">Calculated by Venn</div><span class="eq">5,000.00 − 4,000.00 = 1,000.00 USD outstanding</span></div><div class="finding f-unv" style="margin:0"><div class="h"><span class="badge b-amber nodot">Unverified</span>Not confirmed by any payment record</div>Email says the remaining 1,000.00 was wired. <span class="cite">E3</span></div><div class="rec"><b>Recommended:</b> Request proof of payment<div class="small muted">Human approval applied where policy requires.</div></div></div></div>`;
const PG = {
  '/': () => `<section class="hero"><div class="wrap grid g-wide" style="align-items:center"><div><span class="badge b-blue nodot mb16">For B2B service firms</span><h1>Find the revenue slipping through the cracks.</h1><p class="lead">Venn connects your invoices, payments and customer communications to identify discrepancies, investigate missing revenue and help your team collect what your business is legitimately owed.</p><div class="row wrap">${cta()}<a class="btn btn-lg" href="#how" data-act="scroll" data-id="how">See how it works</a></div><p class="small muted mt16">Venn recommends and records. It never moves money, and your accounting system stays the book of record.</p></div>${mini}</div></section>
  <section class="sec" style="padding:24px 0"><div class="wrap row wrap"><span class="cap">Built for</span>${['Software agencies', 'IT consultancies', 'Managed service providers', 'Staffing agencies', 'Professional services'].map(x => `<span class="badge b-neutral nodot">${x}</span>`).join('')}</div></section>
  ${sec('Where money quietly disappears', 'Financial facts live in different places, so small gaps go unnoticed.', `<div class="grid g3">${feat('card', 'Short and missing payments', 'A customer pays most of an invoice and the rest is never chased.')}${feat('mail', 'Promises in email', '"We already sent it" sits in an inbox with no way to check it against the bank.')}${feat('file', 'Disputes in threads', 'Contract terms, hours and approvals are scattered across PDFs and replies.')}</div>`, 'alt')}
  ${sec('How Venn works', 'One workflow from raw records to a verified outcome.', `<div class="flow"><div class="s"><b>1 · CONNECT</b>Import CSVs or connect your sources.</div><div class="s"><b>2 · DETECT</b>Deterministic rules find short, duplicate and unmatched payments.</div><div class="s"><b>3 · INVESTIGATE</b>Venn gathers evidence and separates facts from guesses.</div><div class="s"><b>4 · APPROVE</b>A person decides. Sensitive actions need an Owner.</div><div class="s"><b>5 · VERIFY</b>Outcomes are confirmed against real payments.</div></div>`, '', 'how')}
  ${sec('Everything the finance team needs, nothing it does not', '', `<div class="grid g3">${feat('git', 'Reconciliation', 'Exact matches applied with undo; uncertain ones wait for a person.')}${feat('search', 'Investigation workspace', 'Evidence, findings, recommendation, approval and resolution in one place.')}${feat('mail', 'Collections', 'Prioritised overdue queue with drafts built from your records.')}${feat('flag', 'Disputes', 'Claims, evidence and decisions tracked to resolution.')}${feat('check', 'Approval center', 'Write-offs, credits and refund decisions with evidence attached.')}${feat('chart', 'Analytics', 'Aging, trends and verified recovery that link back to records.')}</div>`, 'alt')}
  ${sec('The Venn Investigation Engine', 'Not a chatbot. A case file that shows its work.', `<div class="grid g2"><div class="col"><div class="finding f-fact"><div class="h">${ic('check')} Confirmed facts</div>Calculated from stored records, always with a source.</div><div class="finding f-calc"><div class="h">Calculations</div>Exposure and balances computed by code, never by AI.</div><div class="finding f-poss"><div class="h">Possible explanations</div>Hypotheses with their supporting evidence, labelled as such.</div><div class="finding f-unv"><div class="h">Unverified claims</div>What a customer says, kept apart from what the bank shows.</div><div class="finding f-miss"><div class="h">Missing evidence</div>What would settle the question, with a way to request it.</div></div><div class="col"><p>An email saying "we paid" is not a payment. Venn treats emails and documents as supporting evidence and confirms receipt only from bank or payment records.</p><p>The AI proposes; a person decides. It cannot mark an invoice paid, create an allocation, approve a request or send a message.</p><p class="muted">Venn never promises recovery. It shows what is at stake and what is known.</p><a class="btn" href="#/product">Explore the product</a></div></div>`)}
  ${sec('Sources', 'The first release focuses on a small set of sources, each connected with minimum permissions.', `<div class="grid g4 keep2">${[['CSV import', 'Available in the first release'], ['PDF upload', 'Available in the first release'], ['Gmail', 'Planned for the first release'], ['QuickBooks Online', 'Planned for the first release'], ['Stripe (read-only)', 'Planned for the first release'], ['Outlook', 'Planned after'], ['Xero', 'Planned after'], ['Bank feeds', 'Planned after']].map(s => `<div class="feat"><b>${s[0]}</b><div class="small muted">${s[1]}</div></div>`).join('')}</div>`, 'alt')}
  ${sec('Security and trust by design', 'Controls the product is designed around. Certifications: none held today.', `<div class="grid g3">${feat('lock', 'Tenant isolation', 'Every record belongs to one organization and is enforced twice: in code and in the database.')}${feat('shield', 'Server-side permissions', 'Hiding a button is never the control. The server checks every protected action.')}${feat('clock', 'Audit trail', 'Financial and permission changes are recorded and cannot be edited.')}</div><p class="mt16"><a href="#/security">Read more about security</a></p>`)}
  ${sec('Use cases', '', `<div class="grid g2"><div class="feat"><h3>Agency invoices a milestone, the client pays half</h3><p class="muted">See the contract terms and the client\'s email next to the bank record, then decide what to do.</p></div><div class="feat"><h3>Client pays twice</h3><p class="muted">Record the overpayment, get a refund decision approved, and verify it in the bank import.</p></div><div class="feat"><h3>"The wire is on its way"</h3><p class="muted">Keep the claim visible but unverified until a payment record confirms it.</p></div><div class="feat"><h3>Hours disputed</h3><p class="muted">Track the claim, the evidence and the credit decision in one place.</p></div></div>`, 'alt')}
  ${sec('Benefits', '', `<div class="grid g3">${feat('eye', 'Know what is owed and why', 'Every number links to the records behind it.')}${feat('tasks', 'Fewer stalled cases', 'Each investigation has a next step and an owner.')}${feat('lock', 'Decisions on the record', 'Approvals, reasons and outcomes are all logged.')}</div>`)}
  ${sec('Questions', '', FAQ.map(f => `<details class="faq"><summary>${f[0]}</summary><p>${f[1]}</p></details>`).join(''), 'alt')}
  <section class="sec"><div class="wrap" style="text-align:center"><h2>See what your records are hiding</h2><p class="lead" style="margin:0 auto 24px">Book a walkthrough using your own CSV exports.</p>${cta()}</div></section>`,
  '/product': () => `<section class="hero"><div class="wrap"><h1 style="font-size:40px;line-height:48px">One workflow from payment to proof</h1><p class="lead">Six modules that work together around a single case file.</p>${cta()}</div></section>${sec('Modules', '', `<div class="grid g3">${[['git', 'Reconciliation', 'Rules R1–R8 produce matches, suggestions and discrepancies. Only exact matches can auto-apply, and they can be undone.'], ['search', 'Investigations', 'Evidence, findings, recommendation, approval and resolution with citations to stored records.'], ['mail', 'Collections', 'A prioritised queue with drafts checked against record facts before anything is sent.'], ['flag', 'Disputes', 'Customer claims with evidence, timeline and a resolution path that respects approval policy.'], ['check', 'Approval center', 'Impact, evidence and history in one place. Requesters cannot approve their own requests.'], ['chart', 'Analytics', 'Aging, trends, categories and verified recovery, each drilling down to records.']].map(m => feat(m[0], m[1], m[2])).join('')}</div>`)}${sec('Two experiences, one application', 'Owners and AR Specialists see different dashboards, navigation and permissions.', `<div class="grid g2"><div class="feat"><h3>Business Owner</h3><p class="muted">Executive dashboard, approval center, integrations, team, audit log and settings.</p></div><div class="feat"><h3>AR Specialist</h3><p class="muted">A daily work queue: matches to review, investigations, follow-ups, disputes and requests.</p></div></div><p class="mt16"><a class="btn btn-primary" href="app.html">Open the interactive prototype</a></p>`, 'alt')}`,
  '/solutions': () => `<section class="hero"><div class="wrap"><h1 style="font-size:40px;line-height:48px">Built for firms that bill for their time</h1><p class="lead">Negotiated invoices, milestones and purchase orders create discrepancies that off-the-shelf reminders do not explain.</p>${cta()}</div></section>${sec('By segment', '', `<div class="grid g3">${[['Software development agencies', 'Milestone billing, change requests and hours disputes.'], ['IT consulting', 'Statements of work and approval trails in email.'], ['Managed service providers', 'Recurring invoices, usage adjustments and credits.'], ['Staffing and recruitment', 'Timesheet-driven invoices and short pays.'], ['Professional services', 'Retainers, expenses and partial payments.']].map(s => feat('users', s[0], s[1])).join('')}</div>`)}${sec('By role', '', `<div class="grid g2"><div class="feat"><h3>For owners and finance managers</h3><p class="muted">See what is at risk, approve sensitive actions with evidence, and control who can do what.</p></div><div class="feat"><h3>For AR teams</h3><p class="muted">Clear the unmatched list, chase the right invoices and resolve discrepancies faster.</p></div></div>`, 'alt')}`,
  '/security': () => `<section class="hero"><div class="wrap"><h1 style="font-size:40px;line-height:48px">Security you can inspect</h1><p class="lead">What the product is designed to do, stated plainly. Venn holds no security certifications today.</p></div></section>${sec('Controls', '', `<div class="grid g2">${[['Tenant isolation', 'Every record belongs to one organization; access is enforced in application code and again by the database.'], ['Access control', 'Role-based permissions are checked on the server for every action. Owners control team permissions.'], ['Encryption', 'Data is encrypted in transit and at rest. Connection tokens are additionally encrypted and never displayed.'], ['Audit trail', 'Financial changes, approvals and permission changes are recorded in an append-only log.'], ['Human approval', 'Write-offs, credits, refund decisions and final notices need an Owner. The AI cannot approve or send.'], ['AI data handling', 'Customer data is used only to produce your results. You can turn AI features off entirely and keep working.'], ['Minimum permissions', 'Email and accounting connections request only what they need and can be disconnected at any time.'], ['Disclosure', 'Report a vulnerability to security@venn.example (placeholder address for the prototype).']].map(f => `<div class="feat"><h3>${f[0]}</h3><p class="muted">${f[1]}</p></div>`).join('')}</div><p class="small muted mt16">Sub-processors and certifications will be listed here only when real. Prototype copy: verify every statement against the shipped product before publishing.</p>`)}`,
  '/pricing': () => `<section class="hero"><div class="wrap"><h1 style="font-size:40px;line-height:48px">Early access — talk to us</h1><p class="lead">Pricing is not set yet. We are working with a small number of service firms on the first release.</p>${cta('Talk to us')}</div></section>${sec('What is included', '', `<div class="grid g3">${feat('check', 'Unlimited users', 'Invite your whole finance team.')}${feat('git', 'Reconciliation and investigations', 'The full workflow, from import to verified outcome.')}${feat('plug', 'Core integrations', 'CSV, PDF and the first connectors as they become available.')}</div>`)}${sec('Pricing questions', '', `<details class="faq"><summary>Will pricing depend on recovered revenue?</summary><p>No. Venn does not take a share of recovered money, because recovery cannot be promised or reliably attributed.</p></details><details class="faq"><summary>Is there a free trial?</summary><p>Not decided yet. Book a walkthrough using your own CSV exports.</p></details>`, 'alt')}`,
  '/about': () => `<section class="hero"><div class="wrap"><h1 style="font-size:40px;line-height:48px">Evidence first, decisions human</h1><p class="lead">Venn exists to help businesses collect what they are legitimately owed through investigations they can defend.</p></div></section>${sec('Principles', '', `<div class="grid g2">${[['Show the source', 'Every figure and every finding links to the records behind it.'], ['Separate fact from guess', 'Confirmed, possible, unverified and missing are different things.'], ['A person decides', 'AI proposes. People approve consequential actions.'], ['No guarantees', 'Venn surfaces exposure; outcomes depend on customers.']].map(p => `<div class="feat"><h3>${p[0]}</h3><p class="muted">${p[1]}</p></div>`).join('')}</div>`)}`,
  '/contact': () => `<section class="hero"><div class="wrap" style="max-width:640px"><h1 style="font-size:36px;line-height:44px">Book a demo</h1><p class="lead">Tell us about your team. We will reply within two business days.</p><div class="card"><div class="card-b" id="cf">${form('fc', `<div style="position:absolute;left:-9999px" aria-hidden="true"><input name="website" tabindex="-1" autocomplete="off"></div>` + fld('Full name', '<input class="in" data-req name="n">') + fld('Work email', '<input class="in" data-req data-email name="e" type="email">', '', 'Enter a valid work email') + fld('Company', '<input class="in" data-req name="c">') + fld('Company size', '<select class="in"><option>1–10</option><option>11–50</option><option>51–200</option></select>') + fld('How can we help?', '<textarea class="in" rows="4" name="m"></textarea>') + `<p class="small muted mb16">By sending this you agree to be contacted about Venn. See the <a href="#/privacy">privacy policy</a>.</p><button class="btn btn-primary" data-act="sendContact">Request demo</button>`)}<p class="small muted mt8">Prototype: nothing is sent.</p></div></div></div></section>`,
  '/privacy': () => `<section class="sec"><div class="wrap" style="max-width:760px"><div class="banner warn">${ic('info')}<div>Draft — pending legal review. Placeholder structure only.</div></div><h1>Privacy policy</h1>${['What we collect', 'How we use it', 'Sub-processors', 'Retention and deletion', 'Your rights', 'Contact'].map(h => `<h3 class="mt24">${h}</h3><p class="muted">Placeholder. To be written and reviewed by counsel before launch.</p>`).join('')}</div></section>`,
  '/terms': () => `<section class="sec"><div class="wrap" style="max-width:760px"><div class="banner warn">${ic('info')}<div>Draft — pending legal review. Placeholder structure only.</div></div><h1>Terms of service</h1>${['Using Venn', 'Accounts and organizations', 'Your data', 'AI features', 'Limitations', 'Termination'].map(h => `<h3 class="mt24">${h}</h3><p class="muted">Placeholder. To be written and reviewed by counsel before launch.</p>`).join('')}</div></section>`,
};
function renderSite() {
  const p = (location.hash.slice(1) || '/').split('?')[0], pg = PG[p] || (() => `<section class="sec"><div class="wrap"><h1>Page not found</h1><p><a href="#/">Back to home</a></p></div></section>`);
  document.getElementById('root').innerHTML = `<div class="proto"><b>PROTOTYPE</b><span class="hide-s">Marketing site · demo content · nothing is sent</span><span class="sp"></span><a href="app.html">Open the app prototype</a></div>
  <header class="site-nav"><div class="wrap in-w"><a class="logo" href="#/">${LOGO_D}Venn</a><nav aria-label="Main">${NAVL.map(([h, l]) => `<a href="#/${h}" class="${p === '/' + h ? 'on' : ''}">${l}</a>`).join('')}</nav><span class="sp"></span><a class="btn btn-ghost" href="auth.html#/login">Log in</a><a class="btn btn-primary" href="#/contact">Book a demo</a></div></header>
  <main>${pg()}</main>
  <footer class="foot"><div class="wrap grid g4"><div><div class="logo" style="color:#fff;padding:0 0 8px">${LOGO}Venn</div><div class="small">Find the revenue slipping through the cracks.</div></div><div><h4>Product</h4><a href="#/product">Product</a><a href="#/solutions">Solutions</a><a href="#/pricing">Pricing</a></div><div><h4>Company</h4><a href="#/about">About</a><a href="#/security">Security</a><a href="#/contact">Contact</a></div><div><h4>Legal</h4><a href="#/privacy">Privacy</a><a href="#/terms">Terms</a><div class="small mt8">"Venn" is a working name; availability is unverified.</div></div></div></footer>`;
  document.title = 'Venn — ' + (p === '/' ? 'Find the revenue slipping through the cracks' : p.slice(1));
}
render = renderSite;
ACT.scroll = el => { const t = document.getElementById(el.dataset.id); if (t) t.scrollIntoView({ behavior: 'smooth' }); };
ACT.sendContact = () => { const f = $('#fc'); if (!validate(f)) return; if ($('[name=website]', f).value) return; $('#cf').innerHTML = `<div class="empty">${ic('check')}<p><b>Thanks — request received (prototype: nothing was sent).</b></p><a class="btn" href="#/">Back to home</a></div>`; };
window.addEventListener('hashchange', () => window.scrollTo(0, 0));
